'use client';
import { useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { App, URLOpenListenerEvent } from '@capacitor/app';

export default function AppUrlListener() {
  const router = useRouter();

  useEffect(() => {
    // Smoothly dismiss native splash screen once Next.js app mounts
    if (typeof window !== 'undefined') {
      import('@capacitor/splash-screen').then(({ SplashScreen }) => {
        SplashScreen.hide({ fadeOutDuration: 400 }).catch(() => {});
      }).catch(() => {});
    }
  }, []);

  useEffect(() => {
    const initListener = async () => {
      await App.addListener('appUrlOpen', (event: URLOpenListenerEvent) => {
        try {
          const parsedUrl = new URL(event.url);
          
          // 1. Validate Protocol & Host
          if (parsedUrl.protocol !== 'https:') {
            return router.push('/');
          }
          
          const allowedHosts = ['app.trayago.in', 'www.trayago.in'];
          if (!allowedHosts.includes(parsedUrl.hostname)) {
            return router.push('/');
          }

          // 2. Strict Route Allow-list
          const allowedRoutes = [
            '/referral',
            '/reset-password',
            '/verify-email',
            '/login',
            '/promo'
          ];
          
          let targetPath = parsedUrl.pathname;
          
          // Handle trailing slashes gracefully but ensure strict matching
          if (targetPath.length > 1 && targetPath.endsWith('/')) {
              targetPath = targetPath.slice(0, -1);
          }

          if (!allowedRoutes.includes(targetPath)) {
            return router.push('/');
          }

          // 3. Reconstruct safe URL (Path + Query) without host/protocol for internal navigation
          const safeUrl = `${parsedUrl.pathname}${parsedUrl.search}`;
          
          router.push(safeUrl);
        } catch (error) {
          // If URL parsing fails (malformed URL), fallback to home safely
          router.push('/');
        }
      });
    };
    
    // Only run in Capacitor context
    if (typeof window !== 'undefined' && (window as any).Capacitor?.isNative) {
      initListener();
    }
    
    return () => {
      App.removeAllListeners();
    };
  }, [router]);

  return null;
}

