"use client";

import axios from "axios";
import { Crown, LogOut, TrainFront, Menu, X, Sun, Moon, User, ChevronDown, Bell, Sliders } from "lucide-react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import React, { useEffect, useState, useCallback, useRef } from "react";
import { LanguageToggle } from "./LanguageToggle";
import { useLanguage } from "./LanguageContext";
import { useFcmToken } from "../hooks/useFcmToken";
import { motion, AnimatePresence } from "framer-motion";
import { buildAuthHeaders } from "@/lib/authHeaders";
import { ensureAccessToken } from "@/lib/sessionBootstrap";
import { API_BASE, API_HOST } from "@/lib/api";
import { getOrCreateDeviceId } from "@/lib/deviceIdentity";
import { saveReturnUrl } from "@/lib/returnUrl";

export default function Navbar() {
  const { t } = useLanguage();
  const [user, setUser] = useState<any>(null);
  const [status, setStatus] = useState<any>(null);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [activePath, setActivePath] = useState("");
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [userMenuOpen, setUserMenuOpen] = useState(false);

  const pathname = usePathname();
  const router = useRouter();
  const dropdownRef = useRef<HTMLDivElement>(null);
  const notifDropdownRef = useRef<HTMLDivElement>(null);

  // FCM Hook & Notifications UI state
  const { permission, requestPermission, isLoading: isFcmLoading } = useFcmToken();
  const [notifMenuOpen, setNotifMenuOpen] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [isSavingPrefs, setIsSavingPrefs] = useState(false);

  const [prefDelay, setPrefDelay] = useState(true);
  const [prefWaitlist, setPrefWaitlist] = useState(true);
  const [prefPlatform, setPrefPlatform] = useState(true);
  const [prefMarketing, setPrefMarketing] = useState(false);

  const [notifications, setNotifications] = useState<any[]>([]);
  const [notifPage, setNotifPage] = useState(1);
  const [notifTotalPages, setNotifTotalPages] = useState(1);
  const [isNotifLoading, setIsNotifLoading] = useState(false);

  const getHeaders = useCallback(() => buildAuthHeaders(), []);

  const formatTimestamp = useCallback((isoString: string) => {
    if (!isoString) return "";
    try {
      const diffMs = Date.now() - new Date(isoString).getTime();
      const diffMins = Math.floor(diffMs / 60000);
      if (diffMins < 1) return "Just now";
      if (diffMins < 60) return `${diffMins}m ago`;
      const diffHours = Math.floor(diffMins / 60);
      if (diffHours < 24) return `${diffHours}h ago`;
      const diffDays = Math.floor(diffHours / 24);
      return `${diffDays}d ago`;
    } catch (e) {
      return isoString;
    }
  }, []);

  const fetchNotifications = useCallback(async (page: number, append: boolean = false) => {
    const headers = getHeaders();
    if (!headers['Authorization']) {
      setNotifications([]);
      return;
    }
    setIsNotifLoading(true);
    try {
      const response = await axios.get(`${API_HOST}/api/notifications?page=${page}&limit=10`, { headers });
      if (response.data && response.data.success) {
        const mapped = response.data.data.map((item: any) => ({
          id: item.id,
          title: item.title,
          body: item.body,
          read: item.is_read,
          type: item.type || 'info',
          timestamp: formatTimestamp(item.created_at)
        }));

        if (append) {
          setNotifications(prev => {
            const existingIds = new Set(prev.map(p => p.id));
            const filteredMapped = mapped.filter((m: any) => !existingIds.has(m.id));
            return [...prev, ...filteredMapped];
          });
        } else {
          setNotifications(mapped);
        }

        setNotifPage(response.data.pagination.page);
        setNotifTotalPages(response.data.pagination.totalPages);
      }
    } catch (error) {
      console.warn('[NAVBAR] Failed to fetch notifications:', error);
    } finally {
      setIsNotifLoading(false);
    }
  }, [getHeaders, formatTimestamp]);

  const unreadCount = notifications.filter(n => !n.read).length;

  const markAllAsRead = async () => {
    setNotifications(prev => prev.map(n => ({ ...n, read: true })));
    try {
      const headers = getHeaders();
      await axios.post(`${API_HOST}/api/notifications/read-all`, {}, { headers });
    } catch (error) {
      console.warn('[NAVBAR] Failed to mark all notifications as read on server:', error);
    }
  };

  const toggleNotifRead = async (id: string) => {
    const targetNotif = notifications.find(n => n.id === id);
    if (!targetNotif || targetNotif.read) return;

    setNotifications(prev => prev.map(n => n.id === id ? { ...n, read: true } : n));
    try {
      const headers = getHeaders();
      await axios.post(`${API_HOST}/api/notifications/read`, { notificationIds: [id] }, { headers });
    } catch (error) {
      console.warn('[NAVBAR] Failed to mark notification as read on server:', error);
    }
  };

  useEffect(() => {
    fetchNotifications(1);
  }, [user, fetchNotifications]);

  useEffect(() => {
    if (notifMenuOpen) {
      fetchNotifications(1);
    }
  }, [notifMenuOpen, fetchNotifications]);


  // ── Sync Navbar Wallet & Trips Data ──
  const syncNavbarData = useCallback(() => {
    try {
      const userRaw = localStorage.getItem('user');
      if (userRaw && userRaw !== "undefined" && userRaw !== "null") {
        const parsed = JSON.parse(userRaw);
        const updates: any = {};
        if (parsed.plan === "Beta" || parsed.plan?.toLowerCase() === "beta") {
          updates.isBeta = true;
        }
        if (parsed.role === "ADMIN") {
          updates.isAdmin = true;
        }
        if (Object.keys(updates).length > 0) {
          setStatus((prev: any) => ({ ...(prev || {}), ...updates }));
        }
      }
    } catch (e) {
      console.warn('Failed to sync navbar status badges:', e);
    }
  }, []);

  useEffect(() => {
    syncNavbarData();
    window.addEventListener('storage', syncNavbarData);
    return () => {
      window.removeEventListener('storage', syncNavbarData);
    };
  }, [syncNavbarData]);

  // Click outside or scroll to close dropdowns
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setUserMenuOpen(false);
      }
      if (notifDropdownRef.current && !notifDropdownRef.current.contains(event.target as Node)) {
        setNotifMenuOpen(false);
      }
    };
    const handleScroll = () => {
      setUserMenuOpen(false);
      setNotifMenuOpen(false);
    };
    document.addEventListener("mousedown", handleClickOutside);
    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  // Lock body scroll when mobile menu is open to prevent background scrolling overlap
  useEffect(() => {
    if (typeof document !== 'undefined') {
      if (mobileOpen) {
        document.body.style.overflow = 'hidden';
      } else {
        document.body.style.overflow = '';
      }
    }
    return () => {
      if (typeof document !== 'undefined') {
        document.body.style.overflow = '';
      }
    };
  }, [mobileOpen]);

  // Load and save user notification preferences
  useEffect(() => {
    if (typeof window === 'undefined') return;
    
    const savedDelay = localStorage.getItem('pref_delay');
    if (savedDelay !== null) setPrefDelay(savedDelay === 'true');
    const savedWaitlist = localStorage.getItem('pref_waitlist');
    if (savedWaitlist !== null) setPrefWaitlist(savedWaitlist === 'true');
    const savedPlatform = localStorage.getItem('pref_platform');
    if (savedPlatform !== null) setPrefPlatform(savedPlatform === 'true');
    const savedMarketing = localStorage.getItem('pref_marketing');
    if (savedMarketing !== null) setPrefMarketing(savedMarketing === 'true');
  }, []);

  const updatePreference = async (type: string, value: boolean) => {
    if (type === 'delay') setPrefDelay(value);
    else if (type === 'waitlist') setPrefWaitlist(value);
    else if (type === 'platform') setPrefPlatform(value);
    else if (type === 'marketing') setPrefMarketing(value);

    try {
      localStorage.setItem(`pref_${type}`, String(value));
    } catch (e) {}

    try {
      setIsSavingPrefs(true);
      const payload = {
        delay_alerts_enabled: type === 'delay' ? value : prefDelay,
        waitlist_alerts_enabled: type === 'waitlist' ? value : prefWaitlist,
        platform_alerts_enabled: type === 'platform' ? value : prefPlatform,
        marketing_alerts_enabled: type === 'marketing' ? value : prefMarketing,
      };
      await axios.put(`${API_HOST}/api/notifications/preferences`, payload);
    } catch (err) {
      console.warn('[NAVBAR] Failed to save preferences to server, using local fallback:', err);
    } finally {
      setIsSavingPrefs(false);
    }
  };

  useEffect(() => {
    let saved: string | null = null;
    try {
      saved = localStorage.getItem('theme');
    } catch (e) {}

    const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)');

    const applyTheme = (t: 'light' | 'dark') => {
      setTheme(t);
      if (t === 'dark') {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    };

    if (saved === 'dark' || saved === 'light') {
      applyTheme(saved as 'light' | 'dark');
    } else {
      applyTheme(systemPrefersDark.matches ? 'dark' : 'light');
    }

    const handleSystemThemeChange = (e: MediaQueryListEvent) => {
      try {
        if (!localStorage.getItem('theme')) {
          applyTheme(e.matches ? 'dark' : 'light');
        }
      } catch (err) {}
    };

    systemPrefersDark.addEventListener('change', handleSystemThemeChange);
    return () => {
      systemPrefersDark.removeEventListener('change', handleSystemThemeChange);
    };
  }, []);

  const toggleTheme = () => {
    const newTheme = theme === 'dark' ? 'light' : 'dark';
    setTheme(newTheme);
    try {
      localStorage.setItem('theme', newTheme);
    } catch (e) {
      console.warn("Storage disabled: unable to save theme override", e);
    }
    if (newTheme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  };

  useEffect(() => {
    setActivePath(pathname);
  }, [pathname]);

  useEffect(() => {
    try {
      getOrCreateDeviceId();
    } catch (e) {
      console.warn("Storage disabled: unable to persist deviceId", e);
    }

    try {
      let betaCode = "";
      try {
        betaCode = localStorage.getItem("betaCode") || "";
      } catch (e) {
        console.warn("Storage disabled: unable to read betaCode", e);
      }
      
      const urlParams = new URLSearchParams(window.location.search);
      const urlBeta = urlParams.get('beta');
      if (urlBeta) {
        try {
          localStorage.setItem('betaCode', urlBeta);
        } catch (e) {
          console.warn("Storage disabled: unable to save betaCode", e);
        }
        window.history.replaceState({}, document.title, window.location.pathname);
        window.location.reload();
      }

      let raw = null;
      try {
        raw = localStorage.getItem("user");
      } catch (e) {
        console.warn("Storage disabled: unable to read user", e);
      }

      if (raw && raw !== "undefined" && raw !== "null") {
        const parsed = JSON.parse(raw);
        if (parsed && parsed.id) {
          setUser(parsed);
          
          // Register with OneSignal for targeted push notifications
          if (typeof window !== "undefined" && (window as any).OneSignalDeferred) {
            (window as any).OneSignalDeferred.push(function(OneSignal: any) {
              try {
                if (OneSignal && OneSignal.config && OneSignal.config.appId) {
                  OneSignal.login(parsed.id).catch(console.error);
                } else {
                  console.warn("OneSignal not initialized: App ID missing.");
                }
              } catch (err) {
                console.error("OneSignal login failed synchronously:", err);
              }
            });
          }

          ensureAccessToken().then(() => {
            axios.get(`${API_BASE}/auth/status`, {
              params: betaCode ? { betaCode } : undefined,
              headers: buildAuthHeaders(),
            })
              .then(res => {
                setStatus(res.data.data || res.data);
              })
              .catch(() => {});
          });
        } else {
          try {
            localStorage.removeItem("user");
            localStorage.removeItem("accessToken");
            localStorage.removeItem("refreshToken");
          } catch (e) {}
          if (betaCode) checkBetaOnly(betaCode);
        }
      } else if (betaCode) {
        checkBetaOnly(betaCode);
      }
      
      function checkBetaOnly(code: string) {
        axios.get(`${API_BASE}/auth/status?betaCode=${code}`)
          .then(res => {
            if (res.data.data && res.data.data.isBeta) {
              setStatus(res.data.data);
            } else {
              try {
                localStorage.removeItem('betaCode');
              } catch (e) {}
            }
          })
          .catch(() => {
            try {
              localStorage.removeItem('betaCode');
            } catch (e) {}
          });
      }
    } catch (e) {
      try {
        localStorage.removeItem("user");
        localStorage.removeItem("accessToken");
        localStorage.removeItem("refreshToken");
      } catch (innerErr) {}
    }

    const handleAuthRefresh = () => {
      try {
        const raw = localStorage.getItem("user");
        if (raw && raw !== "undefined" && raw !== "null") {
          const parsed = JSON.parse(raw);
          if (parsed && parsed.id) {
            setUser(parsed);
            ensureAccessToken().then(() => {
              axios.get(`${API_BASE}/auth/status`, {
                headers: buildAuthHeaders(),
              })
                .then(res => {
                  setStatus(res.data.data || res.data);
                })
                .catch(() => {});
            });
          }
        }
      } catch {}
    };

    window.addEventListener('auth-change', handleAuthRefresh);
    window.addEventListener('storage', handleAuthRefresh);

    return () => {
      window.removeEventListener('auth-change', handleAuthRefresh);
      window.removeEventListener('storage', handleAuthRefresh);
    };
  }, []);

  const handleLogout = async () => {
    try {
      const fcmToken = localStorage.getItem('fcm_registered_token');
      if (fcmToken) {
        // Attempt to clean up push token from backend. Ignore failures.
        await axios.delete(`${API_HOST}/api/notifications/token`, {
          data: { fcm_token: fcmToken, device_id: localStorage.getItem('deviceId') },
          withCredentials: true,
          headers: buildAuthHeaders()
        }).catch(() => {});
      }
      await axios.post(`${API_HOST}/api/auth/logout`, {}, { withCredentials: true }).catch(() => {});
    } catch (e) {}
    localStorage.removeItem("user");
    localStorage.removeItem("accessToken");
    localStorage.removeItem("refreshToken");
    localStorage.removeItem("betaCode");
    localStorage.removeItem("fcm_registered_token");
    
    if (typeof window !== "undefined" && (window as any).OneSignalDeferred) {
      (window as any).OneSignalDeferred.push(function(OneSignal: any) {
        try {
          if (OneSignal && OneSignal.config && OneSignal.config.appId) {
            OneSignal.logout().catch(console.error);
          }
        } catch (err) {
          console.error("OneSignal logout failed synchronously:", err);
        }
      });
    }

    window.location.href = "/";
  };


  const searchesLeft = status ? (status.isBeta || status.isAdmin || (status.limits?.searches && status.limits.searches >= 9999) ? "∞" : Math.max(0, status.limits?.searches - (status.usage?.searches || 0))) : 3;
  const pnrLeft = status ? (status.isBeta || status.isAdmin || (status.limits?.pnr && status.limits.pnr >= 9999) ? "∞" : Math.max(0, status.limits?.pnr - (status.usage?.pnr || 0))) : 2;
  const liveLeft = status ? (status.isBeta || status.isAdmin || (status.limits?.live && status.limits.live >= 9999) ? "∞" : Math.max(0, status.limits?.live - (status.usage?.live || 0))) : 2;
  const splitMinutesLeft = status?.isBeta ? "∞" : (status?.splitMinutesLeft || 0);

  const handleAiRescueClick = () => {
    setMobileOpen(false);
    if (pathname === '/') {
      const searchContainer = document.getElementById('search-container');
      if (searchContainer) {
        searchContainer.scrollIntoView({ behavior: 'smooth', block: 'center' });
        setTimeout(() => {
          const sourceInput = document.getElementById('source-input');
          if (sourceInput) sourceInput.focus();
        }, 400);
      }
    } else {
      router.push('/#search-container');
    }
  };

  const navLinks = (
    <>
      <Link href="/" onClick={() => setMobileOpen(false)} className={`transition-all duration-200 px-3 py-1.5 rounded-full text-[11px] font-black uppercase tracking-wider ${activePath === '/' ? 'bg-primary/10 text-primary' : 'text-muted hover:text-main hover:bg-input/50'}`}>{t('search')}</Link>
      <Link href="/live" onClick={() => setMobileOpen(false)} className={`transition-all duration-200 px-3 py-1.5 rounded-full text-[11px] font-black uppercase tracking-wider ${activePath === '/live' ? 'bg-primary/10 text-primary' : 'text-muted hover:text-main hover:bg-input/50'}`}>{t('live' as any) || 'Live'}</Link>
      <Link href="/pnr" onClick={() => setMobileOpen(false)} className={`transition-all duration-200 px-3 py-1.5 rounded-full text-[11px] font-black uppercase tracking-wider ${activePath === '/pnr' ? 'bg-primary/10 text-primary' : 'text-muted hover:text-main hover:bg-input/50'}`}>{t('pnr_status')}</Link>
      <Link href="/pricing" onClick={() => setMobileOpen(false)} className={`transition-all duration-200 px-3 py-1.5 rounded-full text-[11px] font-black uppercase tracking-wider ${activePath === '/pricing' ? 'bg-primary/10 text-primary' : 'text-muted hover:text-main hover:bg-input/50'}`}>Pricing</Link>
      <Link href="/news" onClick={() => setMobileOpen(false)} className={`transition-all duration-200 px-3 py-1.5 rounded-full text-[11px] font-black uppercase tracking-wider ${activePath === '/news' ? 'bg-primary/10 text-primary' : 'text-muted hover:text-main hover:bg-input/50'}`}>{t('news' as any) || 'News'}</Link>
      <Link href="/complaint" onClick={() => setMobileOpen(false)} className={`transition-all duration-200 px-3 py-1.5 rounded-full text-[11px] font-black uppercase tracking-wider ${activePath === '/complaint' ? 'bg-red-500/10 text-red-500' : 'text-red-500 hover:text-red-400 hover:bg-input/50'}`}>🚩 {t('register_complaint' as any) || 'Complaint'}</Link>
    </>
  );

  return (
    <nav className="sticky top-0 z-[60] w-full border-b border-subtle bg-card/95 dark:bg-[#0c121e]/95 backdrop-blur-md shadow-xs">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <Link href="/" className="flex items-center gap-2.5 select-none shrink-0 group" aria-label="Trayago Home">
            <div className="w-8 h-8 rounded-xl bg-gradient-to-br from-blue-500 via-blue-600 to-indigo-700 flex items-center justify-center shadow-md shadow-blue-500/20 border border-white/20 group-hover:scale-105 transition-transform duration-200">
              <TrainFront className="w-5 h-5 text-white" />
            </div>
            <span className="text-xl font-display font-black tracking-tighter uppercase text-main">Tray<span className="text-blue-600 dark:text-blue-400">ago</span></span>
          </Link>

          {/* Desktop Nav Links */}
          <div className="hidden xl:flex items-center gap-0.5 text-sm">
            {navLinks}
            {/* AI Rescue — styled as a nav link but with gradient text to stand out */}
            <button
              onClick={handleAiRescueClick}
              className="px-3 py-1.5 rounded-full text-[11px] font-black uppercase tracking-wider bg-premium/10 text-premium border border-premium/30 hover:bg-premium/15 hover:border-premium/50 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-premium/50 cursor-pointer"
              aria-label="AI Rescue"
            >
              🚀 AI Rescue
            </button>
          </div>

          {/* Right Side (Unified Cockpit Panel) */}
          <div className="hidden xl:flex items-center gap-2">
            <div className="hidden xl:block text-xs font-bold text-muted bg-card/85 backdrop-blur-md shadow-sm px-3 py-1.5 rounded-full border border-subtle/50 shrink-0">
              {status?.isAdmin ? (
                <Link href="/admin" className="text-emerald-400 hover:text-emerald-300 transition-colors flex items-center gap-1"><Crown className="w-4 h-4" /> Admin</Link>
              ) : status?.isBeta ? (
                <span className="text-blue-500">🚀 {t('beta_tester')}</span>
              ) : (
                <div className="flex items-center gap-2">
                  <span className="text-muted">{t('free')}:</span>
                  <span className="text-main">🔍 {searchesLeft}</span>
                  <span className="text-main">🎫 {pnrLeft}</span>
                  <span className="text-main">📡 {liveLeft}</span>
                  {splitMinutesLeft !== "∞" && (splitMinutesLeft as number) > 0 && (
                    <span className="text-amber-400">⚡{splitMinutesLeft}m</span>
                  )}
                </div>
              )}
            </div>

            {/* Cockpit Card Container */}
            <div className="flex items-center gap-1.5 bg-card/85 backdrop-blur-md border border-strong rounded-xl p-1 shadow-sm select-none">
              {/* Language Switcher */}
              <div className="relative">
                <LanguageToggle />
              </div>

              {/* Separator */}
              <div className="w-[1px] h-3.5 bg-strong mx-0.5" />

              {/* Theme Toggle */}
              <button 
                onClick={toggleTheme} 
                className="text-muted hover:text-main w-8 h-8 flex items-center justify-center rounded-lg hover:bg-input transition-colors touch-manipulation cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500/50" 
                title="Toggle Theme"
                aria-label="Toggle Theme"
              >
                {theme === 'dark' ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4 text-muted" />}
              </button>

              {/* Push Notifications Bell & Drawer */}
              <div className="relative" ref={notifDropdownRef}>
                <button
                  onClick={() => setNotifMenuOpen(prev => !prev)}
                  className="text-muted hover:text-main w-8 h-8 flex items-center justify-center rounded-lg transition-colors relative touch-manipulation hover:bg-input cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500/50"
                  title="Notifications"
                  aria-label="Notifications"
                >
                  <Bell className="w-4.5 h-4.5" />
                  {unreadCount > 0 && (
                    <span className="absolute top-1.5 right-1.5 w-3.5 h-3.5 rounded-full bg-blue-600 text-white text-[8px] font-black flex items-center justify-center border border-card shadow-sm animate-pulse">
                      {unreadCount}
                    </span>
                  )}
                </button>

                <AnimatePresence>
                  {notifMenuOpen && (
                    <motion.div
                      initial={{ opacity: 0, y: 10, scale: 0.95 }}
                      animate={{ opacity: 1, y: 0, scale: 1 }}
                      exit={{ opacity: 0, y: 8, scale: 0.95 }}
                      transition={{ duration: 0.15, ease: 'easeOut' }}
                      className="absolute right-[-60px] sm:right-0 mt-2 w-80 sm:w-96 bg-card border border-subtle rounded-2xl shadow-elevated p-3.5 z-50 text-left"
                    >
                      <div className="flex items-center justify-between border-b border-subtle pb-2 mb-2">
                        <div className="flex items-center gap-1.5">
                          <Bell className="w-4 h-4 text-blue-600 dark:text-blue-400" />
                          <span className="text-xs font-extrabold uppercase tracking-wider text-main">{t('notifications')}</span>
                        </div>
                        <div className="flex gap-2">
                          <button 
                            onClick={() => setSettingsOpen(prev => !prev)}
                            className="text-[10px] font-black text-muted hover:text-main flex items-center gap-1 bg-input px-2 py-1 rounded-lg transition-all"
                          >
                            <Sliders className="w-3 h-3" />
                            {settingsOpen ? t('feed') : t('settings')}
                          </button>
                          {unreadCount > 0 && (
                            <button 
                              onClick={markAllAsRead}
                              className="text-[10px] font-black text-blue-600 hover:text-blue-500 font-bold"
                            >
                              {t('mark_all_read')}
                            </button>
                          )}
                        </div>
                      </div>

                      {/* Permission Request Banner */}
                      {permission !== 'granted' && (
                        <div className="mb-2 p-2.5 bg-blue-500/10 border border-blue-500/20 rounded-xl flex flex-col gap-1.5">
                          <div className="flex gap-1.5 items-start">
                            <Bell className="w-3.5 h-3.5 text-blue-500 dark:text-blue-400 shrink-0 mt-0.5" />
                            <div>
                              <p className="text-[10px] font-bold text-main">{t('push_disabled')}</p>
                              <p className="text-[9px] text-muted leading-normal">{t('enable_push_desc')}</p>
                            </div>
                          </div>
                          <button
                            onClick={requestPermission}
                            disabled={isFcmLoading}
                            className="w-full text-center bg-blue-600 hover:bg-blue-700 text-white font-extrabold text-[9px] py-1.5 rounded-lg transition-all cursor-pointer"
                          >
                            {isFcmLoading ? t('enabling') : t('enable_now')}
                          </button>
                        </div>
                      )}

                      {/* Settings View */}
                      {settingsOpen ? (
                        <div className="space-y-3 py-1">
                          <p className="text-[10px] font-black uppercase text-muted tracking-wider">{t('alert_preferences')}</p>
                          <div className="space-y-2">
                            <div className="flex items-center justify-between text-xs">
                              <div>
                                <p className="font-bold text-main">{t('delay_notifications')}</p>
                                <p className="text-[9px] text-muted">{t('delay_notifications_desc')}</p>
                              </div>
                              <input 
                                type="checkbox" 
                                checked={prefDelay} 
                                onChange={(e) => updatePreference('delay', e.target.checked)}
                                className="w-4 h-4 rounded text-blue-600 border-subtle bg-input"
                              />
                            </div>
                            <div className="flex items-center justify-between text-xs">
                              <div>
                                <p className="font-bold text-main">{t('waitlist_alerts')}</p>
                                <p className="text-[9px] text-muted">{t('waitlist_alerts_desc')}</p>
                              </div>
                              <input 
                                type="checkbox" 
                                checked={prefWaitlist} 
                                onChange={(e) => updatePreference('waitlist', e.target.checked)}
                                className="w-4 h-4 rounded text-blue-600 border-subtle bg-input"
                              />
                            </div>
                            <div className="flex items-center justify-between text-xs">
                              <div>
                                <p className="font-bold text-main">{t('platform_changes')}</p>
                                <p className="text-[9px] text-muted">{t('platform_changes_desc')}</p>
                              </div>
                              <input 
                                type="checkbox" 
                                checked={prefPlatform} 
                                onChange={(e) => updatePreference('platform', e.target.checked)}
                                className="w-4 h-4 rounded text-blue-600 border-subtle bg-input"
                              />
                            </div>
                            <div className="flex items-center justify-between text-xs">
                              <div>
                                <p className="font-bold text-main">{t('marketing_offers')}</p>
                                <p className="text-[9px] text-muted">{t('marketing_offers_desc')}</p>
                              </div>
                              <input 
                                type="checkbox" 
                                checked={prefMarketing} 
                                onChange={(e) => updatePreference('marketing', e.target.checked)}
                                className="w-4 h-4 rounded text-blue-600 border-subtle bg-input"
                              />
                            </div>
                          </div>
                          {isSavingPrefs && <p className="text-[8px] text-blue-500 animate-pulse text-right">{t('saving_options')}</p>}
                        </div>
                      ) : (
                        /* Notifications Feed View */
                        <div className="max-h-60 overflow-y-auto space-y-1.5 scrollbar-thin">
                          {notifications.length === 0 ? (
                            <div className="py-8 flex flex-col items-center justify-center text-center space-y-2 select-none">
                              <div className="w-12 h-12 rounded-full bg-input/80 flex items-center justify-center border border-subtle text-muted/50">
                                <Bell className="w-5 h-5 stroke-[1.8]" />
                              </div>
                              <div>
                                <p className="text-xs font-extrabold text-main">{t('no_notifications')}</p>
                                <p className="text-[9px] text-muted max-w-[200px] mt-0.5 leading-normal">
                                  You're all caught up! Delayed train alerts and PNR updates will show up here.
                                </p>
                              </div>
                            </div>
                          ) : (
                            <>
                              {notifications.map((n, idx) => (
                                <motion.div 
                                  key={n.id}
                                  initial={{ opacity: 0, x: -8 }}
                                  animate={{ opacity: 1, x: 0 }}
                                  transition={{ delay: idx * 0.03, duration: 0.2 }}
                                  onClick={() => toggleNotifRead(n.id)}
                                  className={`p-2.5 rounded-xl border transition-all cursor-pointer flex gap-2.5 relative select-none ${
                                    n.read 
                                      ? 'bg-transparent border-subtle/30 opacity-70 hover:opacity-100 hover:bg-input/20' 
                                      : 'bg-blue-500/5 border-blue-500/15 hover:bg-blue-500/10 shadow-[0_2px_8px_rgba(59,130,246,0.04)]'
                                  }`}
                                >
                                  {!n.read && (
                                    <span className="absolute top-3 right-3 w-1.5 h-1.5 bg-blue-600 rounded-full" />
                                  )}
                                  <div className={`w-6 h-6 rounded-lg flex items-center justify-center shrink-0 text-[10px] font-bold ${
                                    n.type === 'success' ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/10' :
                                    n.type === 'warning' ? 'bg-amber-500/10 text-amber-400 border border-amber-500/10' :
                                    'bg-blue-500/10 text-blue-500 border border-blue-500/10'
                                  }`}>
                                    {n.type === 'success' ? '✓' : n.type === 'warning' ? '⚠' : 'ℹ'}
                                  </div>
                                  <div className="text-left">
                                    <p className="text-[11px] font-bold text-main leading-snug">{n.title}</p>
                                    <p className="text-[10px] text-muted mt-0.5 leading-normal">{n.body}</p>
                                    <span className="text-[8px] text-muted block mt-1">{n.timestamp}</span>
                                  </div>
                                </motion.div>
                              ))}
                              {notifPage < notifTotalPages && (
                                <button
                                  onClick={() => fetchNotifications(notifPage + 1, true)}
                                  disabled={isNotifLoading}
                                  className="w-full text-center text-[10px] font-black text-blue-600 hover:text-blue-500 py-2 mt-2 bg-input/45 rounded-xl hover:bg-input transition-all disabled:opacity-50 cursor-pointer"
                                >
                                  {isNotifLoading ? (t('loading' as any) || 'Loading...') : (t('load_more' as any) || 'Load More')}
                                </button>
                              )}
                            </>
                          )}
                        </div>
                      )}
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>

              {/* Separator */}
              <div className="w-[1px] h-3.5 bg-strong mx-0.5 hidden sm:block" />

              {/* Desktop User Account Dropdown */}
              <div className="hidden sm:block relative" ref={dropdownRef}>
                <button
                  onClick={() => setUserMenuOpen(prev => !prev)}
                  className="flex items-center gap-1 bg-transparent hover:bg-input rounded-lg px-2 py-1 text-[11px] text-main font-bold transition-all select-none touch-manipulation cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500/50"
                  aria-label="User Account"
                >
                  <div className="w-4 h-4 rounded-full bg-blue-500/10 border border-blue-500/20 flex items-center justify-center text-[8px] text-blue-600 dark:text-blue-400 font-bold overflow-hidden shrink-0">
                    {user?.avatarUrl ? (
                      // eslint-disable-next-line @next/next/no-img-element
                      <img src={user.avatarUrl} alt="User Profile" className="w-full h-full object-cover" />
                    ) : user?.fullName ? (
                      user.fullName[0].toUpperCase()
                    ) : user?.email ? (
                      user.email[0].toUpperCase()
                    ) : (
                      <User className="w-2.5 h-2.5" />
                    )}
                  </div>
                  <span className="max-w-[120px] truncate" title={user?.email || undefined}>{user?.email ? user.email.split('@')[0] : 'Account'}</span>
                  <ChevronDown className={`w-3 h-3 text-muted transition-transform ${userMenuOpen ? 'rotate-180' : ''}`} />
                </button>

                {userMenuOpen && (
                  <div className="absolute right-0 mt-2 w-56 bg-card border border-subtle rounded-2xl shadow-elevated p-2 z-50 animate-in fade-in slide-in-from-top-2 duration-150 text-left">
                    <div className="px-3.5 py-2 border-b border-subtle mb-1">
                      <p className="text-[10px] text-muted font-extrabold uppercase tracking-wider">{t('account')}</p>
                      <p className="text-xs font-bold text-main truncate mt-0.5">{user ? user.email : t('guest_session')}</p>
                      {status?.isAdmin ? (
                        <span className="text-[9px] text-blue-500 flex items-center gap-1 mt-1 font-bold uppercase"><Crown className="w-3 h-3" /> Admin</span>
                      ) : status?.isBeta ? (
                        <span className="text-[9px] text-blue-500 font-bold tracking-wide uppercase mt-1 block">BETA TESTER</span>
                      ) : (status?.planType === 'safar_pro_1d' || user?.planType === 'safar_pro_1d') ? (
                        <span className="text-[9px] text-primary font-bold tracking-wide uppercase mt-1 block">⚡ AI PASS (24H)</span>
                      ) : (status?.planType === 'safar_pro_30m' || user?.planType === 'safar_pro_30m') ? (
                        <span className="text-[9px] text-amber-500 font-bold tracking-wide uppercase mt-1 block">⚡ BLITZ PASS</span>
                      ) : (status?.planType === 'safar_pro_30d' || user?.planType === 'safar_pro_30d') ? (
                        <span className="text-[9px] text-indigo-500 font-bold tracking-wide uppercase mt-1 block">👑 PRO MONTHLY</span>
                      ) : (status?.planType === 'safar_pro_90d' || user?.planType === 'safar_pro_90d') ? (
                        <span className="text-[9px] text-amber-500 font-bold tracking-wide uppercase mt-1 block">🏆 PRO VIP</span>
                      ) : null}
                    </div>
                    


                    <Link
                      href="/profile"
                      onClick={() => setUserMenuOpen(false)}
                      className="flex items-center justify-between px-3.5 py-2 text-xs text-secondary hover:text-main hover:bg-input rounded-xl transition-colors font-bold"
                    >
                      <div className="flex items-center gap-2">
                        <User className="w-3.5 h-3.5 text-blue-500" />
                        <span>{t('profile_settings')}</span>
                      </div>
                      <span className="text-[9px] font-black text-blue-500 bg-blue-500/10 px-1.5 py-0.5 rounded-md">
                        {status?.profileCompletionPercentage || 40}%
                      </span>
                    </Link>

                    <div className="border-t border-subtle my-1" />

                    {user ? (
                      <button
                        onClick={() => {
                          setUserMenuOpen(false);
                          handleLogout();
                        }}
                        className="w-full text-left px-3.5 py-2 text-xs font-bold text-red-500 hover:bg-red-500/10 rounded-xl transition-colors"
                      >
                        {t('logout' as any) || 'Logout'}
                      </button>
                    ) : (
                      <div className="grid grid-cols-2 gap-1.5 p-1">
                        {(() => {
                          const currentPath = typeof window !== 'undefined' ? (window.location.pathname + window.location.search) : '';
                          const hasSearchContext = currentPath.includes('source=') || currentPath.includes('/live/') || currentPath.includes('/trains/');
                          const loginHref = hasSearchContext ? `/login?returnUrl=${encodeURIComponent(currentPath)}` : '/login';
                          const signupHref = hasSearchContext ? `/signup?returnUrl=${encodeURIComponent(currentPath)}` : '/signup';
                          return (
                            <>
                              <Link
                                href={loginHref}
                                onClick={() => {
                                  setUserMenuOpen(false);
                                  if (hasSearchContext) saveReturnUrl(currentPath);
                                }}
                                className="text-center text-[10px] font-black uppercase tracking-wider text-secondary hover:text-main border border-subtle rounded-xl py-1.5 transition-colors"
                              >
                                {t('login' as any) || 'Login'}
                              </Link>
                              <Link
                                href={signupHref}
                                onClick={() => {
                                  setUserMenuOpen(false);
                                  if (hasSearchContext) saveReturnUrl(currentPath);
                                }}
                                className="text-center text-[10px] font-black uppercase tracking-wider bg-blue-600 hover:bg-blue-700 text-white rounded-xl py-1.5 transition-colors"
                              >
                                {t('signup' as any) || 'Sign Up'}
                              </Link>
                            </>
                          );
                        })()}
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>

            {/* Mobile Hamburger */}
            <button
              className="xl:hidden w-11 h-11 flex items-center justify-center text-muted hover:text-main transition-colors touch-manipulation focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500/50"
              onClick={() => setMobileOpen(prev => !prev)}
              aria-label="Toggle menu"
            >
              {mobileOpen ? <X className="w-5.5 h-5.5" /> : <Menu className="w-5.5 h-5.5" />}
            </button>
          </div>
        </div>

      {/* Mobile Dropdown Menu */}
      {mobileOpen && (
        <div className="xl:hidden border-t border-subtle bg-card/95 backdrop-blur-xl shadow-2xl px-4 py-4 space-y-4 animate-in slide-in-from-top-2 duration-200 text-left max-h-[calc(100dvh-4.5rem)] overflow-y-auto overscroll-contain">
          {/* Primary Navigation Links (crucial for tablets where BottomNav is hidden) */}
          <div className="flex flex-col gap-1 border-b border-subtle pb-3">
            <p className="text-[9px] text-muted font-extrabold uppercase tracking-widest pl-1 mb-1">{t('navigation' as any) || 'Navigation'}</p>
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-1.5 text-xs font-bold">
              <Link href="/" onClick={() => setMobileOpen(false)} className={`flex items-center gap-2 px-3 py-2 rounded-xl transition-colors ${activePath === '/' ? 'bg-primary/10 text-primary' : 'text-secondary hover:text-main hover:bg-input/50'}`}>
                <span>🔍 {t('search')}</span>
              </Link>
              <Link href="/live" onClick={() => setMobileOpen(false)} className={`flex items-center gap-2 px-3 py-2 rounded-xl transition-colors ${activePath === '/live' ? 'bg-primary/10 text-primary' : 'text-secondary hover:text-main hover:bg-input/50'}`}>
                <span>📡 {t('live' as any) || 'Live'}</span>
              </Link>
              <Link href="/pnr" onClick={() => setMobileOpen(false)} className={`flex items-center gap-2 px-3 py-2 rounded-xl transition-colors ${activePath === '/pnr' ? 'bg-primary/10 text-primary' : 'text-secondary hover:text-main hover:bg-input/50'}`}>
                <span>🎫 {t('pnr_status')}</span>
              </Link>
              <Link href="/pricing" onClick={() => setMobileOpen(false)} className={`flex items-center gap-2 px-3 py-2 rounded-xl transition-colors ${activePath === '/pricing' ? 'bg-primary/10 text-primary' : 'text-secondary hover:text-main hover:bg-input/50'}`}>
                <span>✦ Pricing</span>
              </Link>
              <Link href="/news" onClick={() => setMobileOpen(false)} className={`flex items-center gap-2 px-3 py-2 rounded-xl transition-colors ${activePath === '/news' ? 'bg-primary/10 text-primary' : 'text-secondary hover:text-main hover:bg-input/50'}`}>
                <span>📰 {t('news' as any) || 'News'}</span>
              </Link>
              <button
                onClick={handleAiRescueClick}
                className="flex items-center gap-2 px-3 py-2 rounded-xl transition-colors text-left bg-premium/10 text-premium border border-premium/30 hover:bg-premium/15 cursor-pointer"
                aria-label="AI Rescue"
              >
                <span>🚀 AI Rescue</span>
              </button>
            </div>
          </div>

          <div className="flex flex-col gap-3 text-sm font-semibold">
            <Link href="/feedback" onClick={() => setMobileOpen(false)} className={`transition-colors ${activePath === '/feedback' ? 'text-blue-500 hover:text-blue-600' : 'text-muted hover:text-main'}`}>💬 {t('send_feedback' as any) || 'Send Feedback'}</Link>
          </div>

          {/* Services Drawer Relocated Links for mobile */}
          <div className="border-t border-subtle pt-3.5 flex flex-col gap-2.5">
            <p className="text-[9px] text-muted font-extrabold uppercase tracking-widest pl-1">{t('my_dashboard' as any)}</p>
            


            <Link
              href="/profile"
              onClick={() => setMobileOpen(false)}
              className="flex items-center justify-between text-sm text-secondary hover:text-main px-1 py-1 font-bold"
            >
              <div className="flex items-center gap-2">
                <User className="w-4 h-4 text-blue-500" />
                <span>{t('profile_settings')}</span>
              </div>
              <span className="text-[9px] font-black text-blue-500 bg-blue-500/10 px-1.5 py-0.5 rounded-md">
                {status?.profileCompletionPercentage || 40}%
              </span>
            </Link>
          </div>

          <div className="border-t border-subtle pt-3.5 flex flex-col gap-3">
            {user ? (
              <div className="flex items-center justify-between">
                <div>
                  <span className="text-xs text-main font-bold block">{user?.email || 'User'}</span>
                  {status?.isAdmin ? (
                    <span className="text-[9px] text-emerald-500 font-bold uppercase block mt-0.5 flex items-center gap-1"><Crown className="w-3 h-3" /> ADMIN</span>
                  ) : status?.isBeta ? (
                    <span className="text-[9px] text-blue-500 font-bold uppercase block mt-0.5">BETA TESTER</span>
                  ) : (status?.planType === 'safar_pro_1d' || user?.planType === 'safar_pro_1d') ? (
                    <span className="text-[9px] text-primary font-bold uppercase block mt-0.5">⚡ AI PASS (24H) ACTIVE</span>
                  ) : (status?.planType === 'safar_pro_30m' || user?.planType === 'safar_pro_30m') ? (
                    <span className="text-[9px] text-amber-500 font-bold uppercase block mt-0.5">⚡ BLITZ PASS ACTIVE</span>
                  ) : (status?.planType === 'safar_pro_30d' || user?.planType === 'safar_pro_30d') ? (
                    <span className="text-[9px] text-indigo-500 font-bold uppercase block mt-0.5">👑 PRO MONTHLY ACTIVE</span>
                  ) : (status?.planType === 'safar_pro_90d' || user?.planType === 'safar_pro_90d') ? (
                    <span className="text-[9px] text-amber-500 font-bold uppercase block mt-0.5">🏆 PRO VIP ACTIVE</span>
                  ) : null}
                </div>
                <button onClick={() => { setMobileOpen(false); handleLogout(); }} className="text-xs text-red-500 hover:text-red-600 flex items-center gap-1 font-bold">
                  <LogOut className="w-3.5 h-3.5" /> {t('logout' as any) || 'Logout'}
                </button>
              </div>
            ) : (
              <div className="flex gap-3">
                {(() => {
                  const currentPath = typeof window !== 'undefined' ? (window.location.pathname + window.location.search) : '';
                  const hasSearchContext = currentPath.includes('source=') || currentPath.includes('/live/') || currentPath.includes('/trains/');
                  const loginHref = hasSearchContext ? `/login?returnUrl=${encodeURIComponent(currentPath)}` : '/login';
                  const signupHref = hasSearchContext ? `/signup?returnUrl=${encodeURIComponent(currentPath)}` : '/signup';
                  return (
                    <>
                      <Link
                        href={loginHref}
                        onClick={() => {
                          setMobileOpen(false);
                          if (hasSearchContext) saveReturnUrl(currentPath);
                        }}
                        className="flex-1 text-center text-xs font-bold text-secondary hover:text-main border border-subtle rounded-xl py-2 transition-colors"
                      >
                        {t('login' as any) || 'Login'}
                      </Link>
                      <Link
                        href={signupHref}
                        onClick={() => {
                          setMobileOpen(false);
                          if (hasSearchContext) saveReturnUrl(currentPath);
                        }}
                        className="flex-1 text-center text-xs font-bold px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl transition-colors"
                      >
                        {t('signup' as any) || 'Sign Up'}
                      </Link>
                    </>
                  );
                })()}
              </div>
            )}
            {/* Mobile usage counter */}
            <div className="text-[10px] text-muted flex gap-3 font-semibold justify-center">
              {status?.isBeta ? (
                <span className="text-blue-500">🚀 {t('beta_mode_active' as any)}</span>
              ) : status?.isAdmin ? (
                <Link href="/pricing" className="text-emerald-400 hover:text-emerald-300 transition-colors">✦ Pricing</Link>
              ) : (
                <>
                  <span>🔍 {searchesLeft}</span>
                  <span>🎫 {pnrLeft}</span>
                  <span>📡 {liveLeft}</span>
                </>
              )}
            </div>
          </div>
        </div>
      )}
    </nav>
  );
}
