"use client";

import axios from 'axios';
import { useEffect } from 'react';
import api, { API_BASE, isPublicAuthEndpoint } from '@/lib/api';
import { getOrCreateDeviceId } from '@/lib/deviceIdentity';

// PHASE_4C759 Fix #2 (P1-SEC-003): CSRF token storage (memory-only, not localStorage)
let csrfToken: string | null = null;

let isRefreshing = false;
let failedQueue: any[] = [];

const processQueue = (error: any, token: string | null = null) => {
  failedQueue.forEach(prom => {
    if (error) {
      prom.reject(error);
    } else {
      prom.resolve(token);
    }
  });
  failedQueue = [];
};

export const REFRESH_UNAUTHENTICATED_MARKER = Object.freeze({ __preserveUpstream401: true });

export interface RefreshFailureResolution {
  queueError: unknown;
  rejectedError: unknown;
  shouldClearTokens: boolean;
  redirectBlockedLogin: boolean;
  isUnexpectedFailure: boolean;
}

/**
 * Classifies a failed reactive /auth/refresh attempt following an upstream 401.
 * Expected auth rejections preserve the upstream 401 error (e.g. REQUIRE_LOGIN / UNAUTHORIZED)
 * while genuine network/5xx refresh failures remain observable to callers and telemetry.
 */
interface AxiosLikeError {
  response?: {
    status?: number;
    data?: { error?: string; code?: string };
  };
}

export function resolveRefreshFailure(
  upstreamError: unknown,
  refreshError: unknown
): RefreshFailureResolution {
  if (refreshError === REFRESH_UNAUTHENTICATED_MARKER) {
    return {
      queueError: REFRESH_UNAUTHENTICATED_MARKER,
      rejectedError: upstreamError,
      shouldClearTokens: false,
      redirectBlockedLogin: false,
      isUnexpectedFailure: false,
    };
  }

  const refreshResponse = (refreshError as AxiosLikeError | null | undefined)?.response;
  const refreshStatus = refreshResponse?.status;
  const refreshCode = refreshResponse?.data?.error;

  if (refreshStatus === 401) {
    return {
      queueError: REFRESH_UNAUTHENTICATED_MARKER,
      rejectedError: upstreamError,
      shouldClearTokens: true,
      redirectBlockedLogin: false,
      isUnexpectedFailure: false,
    };
  }

  if (refreshStatus === 403 && refreshCode === 'account_blocked') {
    return {
      queueError: refreshError,
      rejectedError: refreshError,
      shouldClearTokens: true,
      redirectBlockedLogin: true,
      isUnexpectedFailure: false,
    };
  }

  return {
    queueError: refreshError,
    rejectedError: refreshError,
    shouldClearTokens: false,
    redirectBlockedLogin: false,
    isUnexpectedFailure: true,
  };
}

/**
 * PHASE_4C970 — Proactive token refresh helper.
 * Decodes JWT (no signature check — just payload inspection) and returns
 * true if the token will expire within the next 30 minutes.
 */
function isTokenExpiringSoon(token: string | null): boolean {
  if (!token) return false;
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return false;
    const payload = JSON.parse(atob(parts[1]));
    const exp = payload?.exp;
    if (!exp) return false;
    const nowSec = Math.floor(Date.now() / 1000);
    // Refresh if less than 30 minutes (1800 seconds) remaining
    return (exp - nowSec) < 1800;
  } catch {
    return false;
  }
}

/**
 * PHASE_4C970 — Silent proactive refresh (does not touch failedQueue).
 * Called from the request interceptor so the user never sees a 401.
 */
async function proactiveRefresh(): Promise<void> {
  if (isRefreshing) return; // another refresh already in flight
  isRefreshing = true;
  try {
    let storedRefreshToken: string | null = null;
    try { storedRefreshToken = localStorage.getItem('refreshToken'); } catch {}

    const res = await axios.post(
      `${API_BASE}/auth/refresh`,
      storedRefreshToken ? { refreshToken: storedRefreshToken } : {},
      {
        withCredentials: true,
        headers: storedRefreshToken ? { Authorization: `Bearer ${storedRefreshToken}` } : {}
      }
    );

    if (res.data.success && res.data.accessToken) {
      try {
        localStorage.setItem('accessToken', res.data.accessToken);
        if (res.data.refreshToken) {
          localStorage.setItem('refreshToken', res.data.refreshToken);
        }
      } catch {}
    }
  } catch (err: any) {
    // If refresh token is rejected as invalid/unauthorized (401), clean up dead tokens
    if (err?.response?.status === 401) {
      try {
        localStorage.removeItem('accessToken');
        localStorage.removeItem('refreshToken');
      } catch {}
    }
  } finally {
    isRefreshing = false;
  }
}

export function AxiosInterceptor() {
  useEffect(() => {
    const registerForInstance = (instance: typeof axios | typeof api) => {
      const requestInterceptor = instance.interceptors.request.use(async (config: any) => {
        try {
          // Add Beta Tester Code
          const betaCode = localStorage.getItem('betaCode');
          if (betaCode) {
            config.headers['x-beta-code'] = betaCode;
          }
          // Add Language Header for i18n API support
          const lang = localStorage.getItem('trayago_lang') || 'en';
          config.headers['Accept-Language'] = lang;

          // PHASE_4C967: Identity is JWT-only server-side (P0-001). Do not send x-user-id.

          // Guard: Never perform proactive refresh or attach Authorization header on public auth endpoints
          const isAuthEndpoint = isPublicAuthEndpoint(config.url);

          // PHASE_4C970: Proactive refresh — silently renew access token 30 min before expiry
          // This prevents the user from ever hitting a 401 due to token expiry
          const accessToken = localStorage.getItem('accessToken');
          if (!isAuthEndpoint && accessToken && isTokenExpiringSoon(accessToken)) {
            await proactiveRefresh();
          }

          // Add the (potentially just-refreshed) access token for protected endpoints ONLY.
          const freshToken = localStorage.getItem('accessToken');
          if (!isAuthEndpoint && freshToken) {
            config.headers['Authorization'] = `Bearer ${freshToken}`;
          }

          // Add Device ID
          const deviceId = getOrCreateDeviceId();
          if (deviceId) {
            config.headers['x-device-id'] = deviceId;
          }

          // PHASE_4C759 Fix #2 (P1-SEC-003): Include CSRF token for state-changing requests
          if (!csrfToken && typeof window !== 'undefined' && (window as any).__trayago_csrf) {
            csrfToken = (window as any).__trayago_csrf;
          }
          if (csrfToken && config.method && !['get', 'head', 'options'].includes(config.method.toLowerCase())) {
            config.headers['X-CSRF-Token'] = csrfToken;
          }
        } catch (e) {
          console.warn("Storage disabled: unable to populate auth headers in axios", e);
        }
        
        return config;
      });

      const responseInterceptor = instance.interceptors.response.use(
        (response: any) => {
          // PHASE_4C759 Fix #2 (P1-SEC-003): Extract CSRF token from response headers or data payload
          const token = response.headers?.['x-csrf-token'] || response.headers?.['X-CSRF-Token'] || response.data?.csrfToken;
          if (token) {
            csrfToken = token;
            if (typeof window !== 'undefined') (window as any).__trayago_csrf = token;
          }
          return response;
        },
        async (error: any) => {
          // Extract CSRF token even on errors (e.g. 401 from /auth/status)
          const token = error.response?.headers?.['x-csrf-token'] || error.response?.headers?.['X-CSRF-Token'] || error.response?.data?.csrfToken;
          if (token) {
            csrfToken = token;
            if (typeof window !== 'undefined') (window as any).__trayago_csrf = token;
          }

          function safeRedirectToLogin(target = '/login') {
            if (typeof window !== 'undefined' && !window.location.pathname.startsWith('/login')) {
              window.location.href = target;
            }
          }

          if (error.response?.status === 403 && error.response?.data?.error === 'account_blocked') {
            try {
              localStorage.removeItem('user');
              localStorage.removeItem('accessToken');
              localStorage.removeItem('refreshToken');
            } catch (e) {}
            safeRedirectToLogin('/login?blocked=true');
            return Promise.reject(error);
          }

          if (error.response?.status === 401) {
            // Never trigger refresh loops or intercept 401 on public auth endpoints (login, signup, google-login, etc.)
            if (!error.config?._retry && !isPublicAuthEndpoint(error.config?.url)) {
              error.config._retry = true;

              if (isRefreshing) {
                return new Promise(function(resolve, reject) {
                  failedQueue.push({ resolve, reject });
                }).then(token => {
                  error.config.headers = error.config.headers || {};
                  error.config.headers['Authorization'] = 'Bearer ' + token;
                  return instance(error.config);
                }).catch(err => {
                  return Promise.reject(err === REFRESH_UNAUTHENTICATED_MARKER ? error : err);
                });
              }

              isRefreshing = true;

              try {
                // Primary: try cookie-based refresh (works same-domain)
                // Fallback: send stored refresh token in body & header (works cross-domain .com/.online)
                let storedRefreshToken: string | null = null;
                try { storedRefreshToken = localStorage.getItem('refreshToken'); } catch (e) {}

                const res = await axios.post(
                  `${API_BASE}/auth/refresh`,
                  storedRefreshToken ? { refreshToken: storedRefreshToken } : {},
                  {
                    withCredentials: true,
                    headers: storedRefreshToken ? { Authorization: `Bearer ${storedRefreshToken}` } : {}
                  }
                );
                if (res.data?.success && res.data?.accessToken) {
                  try {
                    localStorage.setItem('accessToken', res.data.accessToken);
                    // Store new refresh token so next cycle works too
                    if (res.data.refreshToken) {
                      localStorage.setItem('refreshToken', res.data.refreshToken);
                    }
                  } catch (e) {}
                  error.config.headers = error.config.headers || {};
                  error.config.headers['Authorization'] = `Bearer ${res.data.accessToken}`;
                  processQueue(null, res.data.accessToken);
                  return instance(error.config);
                } else {
                  const outcome = resolveRefreshFailure(error, REFRESH_UNAUTHENTICATED_MARKER);
                  processQueue(outcome.queueError, null);
                  return Promise.reject(outcome.rejectedError);
                }
              } catch (refreshError: any) {
                const outcome = resolveRefreshFailure(error, refreshError);
                if (outcome.shouldClearTokens) {
                  try {
                    localStorage.removeItem('user');
                    localStorage.removeItem('accessToken');
                    localStorage.removeItem('refreshToken');
                  } catch (e) {}
                }
                if (outcome.redirectBlockedLogin) {
                  safeRedirectToLogin('/login?blocked=true');
                }
                if (outcome.isUnexpectedFailure) {
                  console.error('AxiosInterceptor: Token refresh failed unexpectedly:', refreshError);
                }
                processQueue(outcome.queueError, null);
                return Promise.reject(outcome.rejectedError);
              } finally {
                isRefreshing = false;
              }
            }
          }

          // 2. Exponential Backoff Retry Policy for Idempotent GET requests ONLY
          const config = error.config;
          const isGetRequest = config?.method?.toLowerCase() === 'get';
          const isNetworkOrServerError = !error.response || (error.response.status >= 500 && error.response.status <= 599);

          if (isGetRequest && isNetworkOrServerError && config) {
            config._retryCount = config._retryCount || 0;
            if (config._retryCount < 3) {
              config._retryCount += 1;
              const delay = 500 * Math.pow(2, config._retryCount - 1);
              console.warn(`AxiosInterceptor: Retrying GET ${config.url} (${config._retryCount}/3) in ${delay}ms`);
              await new Promise(resolve => setTimeout(resolve, delay));
              return instance(config);
            }
          }

          return Promise.reject(error);
        }
      );

      return { requestInterceptor, responseInterceptor };
    };

    const globalInterceptors = registerForInstance(axios);
    const apiInterceptors = registerForInstance(api);

    // Bootstrap CSRF token on startup if missing so initial form submissions never encounter CSRF_INVALID
    if (!csrfToken && typeof window !== 'undefined') {
      axios.get(`${API_BASE}/auth/csrf-token`, { withCredentials: true })
        .then(res => {
          const t = res.data?.csrfToken || res.headers?.['x-csrf-token'] || res.headers?.['X-CSRF-Token'];
          if (t) {
            csrfToken = t;
            (window as any).__trayago_csrf = t;
          }
        })
        .catch(() => {});
    }

    return () => {
      axios.interceptors.request.eject(globalInterceptors.requestInterceptor);
      axios.interceptors.response.eject(globalInterceptors.responseInterceptor);
      api.interceptors.request.eject(apiInterceptors.requestInterceptor);
      api.interceptors.response.eject(apiInterceptors.responseInterceptor);
    };
  }, []);

  return null;
}
