import { getOrCreateDeviceId } from './deviceIdentity';

/**
 * PHASE_4C967 — Client auth headers for entitlement APIs.
 * Identity is JWT-only server-side (P0-001). Never send x-user-id.
 */
export function buildAuthHeaders(): Record<string, string> {
  if (typeof window === 'undefined') return {};

  const headers: Record<string, string> = {};

  try {
    const accessToken = localStorage.getItem('accessToken');
    if (accessToken) {
      headers['Authorization'] = `Bearer ${accessToken}`;
    }

    const deviceId = getOrCreateDeviceId();
    if (deviceId) {
      headers['x-device-id'] = deviceId;
    }

    const betaCode = localStorage.getItem('betaCode');
    if (betaCode) {
      headers['x-beta-code'] = betaCode;
    }
  } catch {
    // Storage disabled — return empty headers
  }

  return headers;
}