'use client';

import React from 'react';

interface Props {
  children: React.ReactNode;
}

interface State {
  hasError: boolean;
  errorId?: string;
}

/**
 * Safely capture an exception to Sentry using the Sentry Store API.
 * 
 * @sentry/nextjs is incompatible with Next.js 16 (peer dep mismatch).
 * This function uses the Sentry HTTP Store API directly — no SDK required.
 * DSN format: https://<key>@<host>/sentry/<projectId>
 * Store endpoint: https://<host>/sentry/<projectId>/store/
 *
 * When @sentry/nextjs officially supports Next.js 16, replace this
 * with: import * as Sentry from "@sentry/nextjs"; Sentry.captureException(error);
 */
function safeCaptureException(error: Error, extra?: Record<string, unknown>): string | undefined {
  // Always log to console
  console.error('[GlobalErrorBoundary]', error.message, extra);

  const dsn = process.env.NEXT_PUBLIC_SENTRY_DSN;
  if (!dsn || process.env.NODE_ENV !== 'production') return undefined;

  try {
    // Parse DSN: https://<publicKey>@<host>/sentry/<projectId>
    const dsnUrl = new URL(dsn);
    const publicKey = dsnUrl.username;
    const projectId = dsnUrl.pathname.replace('/sentry/', '').replace('/', '');
    const storeEndpoint = `${dsnUrl.protocol}//${dsnUrl.host}/sentry/${projectId}/store/`;

    const errorId = Math.random().toString(36).substring(2, 18);
    const envelope = {
      event_id: errorId,
      timestamp: new Date().toISOString(),
      platform: 'javascript',
      environment: 'production',
      level: 'error',
      exception: {
        values: [{
          type: error.name || 'Error',
          value: error.message,
          stacktrace: {
            frames: (error.stack || '').split('\n').slice(1, 10).map(line => ({
              filename: line.trim().split(' ').pop() || 'unknown',
              function: line.trim().split(' ')[1] || 'unknown',
            }))
          }
        }]
      },
      tags: {
        boundary: 'GlobalErrorBoundary',
        url: typeof window !== 'undefined' ? window.location.pathname : 'unknown'
      },
      extra: extra || {}
    };

    // Fire-and-forget — never block UI for error reporting
    fetch(storeEndpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Sentry-Auth': `Sentry sentry_version=7, sentry_key=${publicKey}`
      },
      body: JSON.stringify(envelope),
      keepalive: true // survive page unload
    }).catch(() => {
      // Silently ignore if Sentry is unreachable
    });

    return errorId;
  } catch {
    // DSN parse error or network issue — fail silently
    return undefined;
  }
}

/**
 * Global React Error Boundary.
 * Catches any render-time crash in the subtree,
 * reports it to Sentry, and shows a safe fallback UI.
 * Never exposes stack traces or internal data to the user.
 */
export class GlobalErrorBoundary extends React.Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(): State {
    return { hasError: true };
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    const errorId = safeCaptureException(error, { componentStack: info.componentStack });
    this.setState({ errorId });
  }

  render() {
    if (this.state.hasError) {
      return (
        <div
          style={{
            minHeight: '100vh',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            background: '#0a0a0f',
            color: '#e2e8f0',
            fontFamily: 'system-ui, sans-serif',
            textAlign: 'center',
            padding: '2rem',
          }}
        >
          <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>🚂</div>
          <h1 style={{ fontSize: '1.5rem', fontWeight: 700, color: '#a855f7', marginBottom: '0.5rem' }}>
            Something went wrong
          </h1>
          <p style={{ color: '#94a3b8', marginBottom: '1.5rem', maxWidth: '400px' }}>
            Trayago hit an unexpected error. Our team has been notified automatically.
          </p>
          <button
            onClick={() => {
              this.setState({ hasError: false });
              window.location.href = '/';
            }}
            style={{
              background: 'linear-gradient(135deg, #a855f7, #7c3aed)',
              color: '#fff',
              border: 'none',
              padding: '0.75rem 2rem',
              borderRadius: '0.75rem',
              fontSize: '0.9rem',
              fontWeight: 600,
              cursor: 'pointer',
            }}
          >
            Return to Home
          </button>
          {this.state.errorId && (
            <p style={{ color: '#475569', fontSize: '0.7rem', marginTop: '1rem' }}>
              Error ID: {this.state.errorId}
            </p>
          )}
        </div>
      );
    }

    return this.props.children;
  }
}
